1349	  /**
1350	   * GET /api/plugins/:pluginId/bridge/stream/:channel
1351	   *
1352	   * Server-Sent Events endpoint for real-time streaming from plugin worker to UI.
1353	   *
1354	   * The worker pushes events via `ctx.streams.emit(channel, event)` which arrive
1355	   * as JSON-RPC notifications to the host, get published on the PluginStreamBus,
1356	   * and are fanned out to all connected SSE clients matching (pluginId, channel,
1357	   * companyId).
1358	   *
1359	   * Query parameters:
1360	   * - `companyId` (required): Scope events to a specific company
1361	   *
1362	   * SSE event types:
1363	   * - `message`: A data event from the worker (default)
1364	   * - `open`: The worker opened the stream channel
1365	   * - `close`: The worker closed the stream channel — client should disconnect
1366	   *
1367	   * Errors:
1368	   * - 400 if companyId is missing
1369	   * - 404 if plugin not found
1370	   * - 501 if bridge deps or stream bus are not configured
1371	   */
1372	  router.get("/plugins/:pluginId/bridge/stream/:channel", async (req, res) => {
